/* ERPNext Web Page > Scripting */
(function () {
  'use strict';

  var R = document.getElementById('sales-master-root');
  if (!R) { void 0; return; }
  if (R.__salesMasterWebPageInitialized) { return; }
  R.__salesMasterWebPageInitialized = true;

  var REPORT_NAME = 'REFERRAL REPORT – FIXED';
  var PAGE_SIZE = 20;

  var fromEl = R.querySelector('#rr_from');
  var toEl = R.querySelector('#rr_to');
  var customerEl = R.querySelector('#rr_customer');
  var paidFromEl = R.querySelector('#rr_amt_from');
  var paidToEl = R.querySelector('#rr_amt_to');
  var outstandingOperatorEl = R.querySelector('#rr_out_operator');
  var outstandingValueEl = R.querySelector('#rr_out_value');
  var applyButton = R.querySelector('#rr_apply_btn');
  var downloadButton = R.querySelector('#rr_dl_btn');
  var messageEl = R.querySelector('#rr_msg');
  var tableWrapper = R.querySelector('#rr_tbl_wrap');

  var allRows = [];
  var filteredRows = [];
  var currentPage = 1;
  var userBranch = '';
  var permittedBranches = [];
  var branchAccessRestricted = false;
  var selectedFormat = 'Excel';
  var requestInProgress = false;
  var lastAppliedSignature = '';
  var totalRowSourceIndex = null;

  var requiredElements = [fromEl,toEl,customerEl,paidFromEl,paidToEl,outstandingOperatorEl,outstandingValueEl,applyButton,downloadButton,messageEl,tableWrapper];
  if (requiredElements.some(function (e) { return !e; })) { void 0; return; }

  function pad(v){ return String(v).padStart(2,'0'); }
  function isObjectRow(v){ return v && typeof v==='object' && !Array.isArray(v); }
  function escapeHtml(v){ return String(v===null||v===undefined?'':v).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#039;'); }
  function showMessage(t,c){ messageEl.style.display='block'; messageEl.style.color=c||'#595959'; messageEl.textContent=t; }
  function setButtonState(b,busy,busyText,normalText){ if(!b) return; b.disabled=!!busy; b.textContent=busy?busyText:normalText; }
  function setBusyState(busy,activeButton){ requestInProgress=!!busy; applyButton.disabled=!!busy; downloadButton.disabled=!!busy; if(!busy){ applyButton.textContent='Apply Filters'; downloadButton.textContent='Generate & Download'; return; } if(activeButton===applyButton){ applyButton.textContent='Applying...'; } if(activeButton===downloadButton){ downloadButton.textContent='Preparing...'; } }
  function parseAmount(v){ if(v===null||v===undefined||String(v).trim()===''){ return null; } var c=String(v).replace(/₹/g,'').replace(/,/g,'').replace(/\s/g,'').trim(); var n=Number(c); return Number.isFinite(n)?n:null; }
  function formatDisplayDate(v){ if(!v){ return ''; } var raw=String(v).slice(0,10); var p=raw.split('-'); if(p.length!==3){ return String(v); } var y=parseInt(p[0],10),m=parseInt(p[1],10),d=parseInt(p[2],10); if(!Number.isFinite(y)||!Number.isFinite(m)||!Number.isFinite(d)){ return String(v); } var mn=['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec']; return String(d).padStart(2,'0')+'-'+mn[m-1]+'-'+String(y).slice(-2); }
  function formatCurrency(v){ if(v===null||v===undefined||v===''){ return ''; } var n=Number(v); if(!Number.isFinite(n)){ return escapeHtml(v); } return '₹'+n.toLocaleString('en-IN',{minimumFractionDigits:2,maximumFractionDigits:2}); }

  function numberOrZero(v){
    var n=parseAmount(v);
    return n===null?0:n;
  }

  function roundMoney(v){
    return Math.round((numberOrZero(v)+Number.EPSILON)*100)/100;
  }

  /*
    Normalize REFERRAL REPORT – FIXED output for this Web Page.

    The report supplies:
      invoice_date
      referring_employee
      incentive_employee
      paid_amount
      gst_amount
      paid_amount_without_gst

    The table previously looked for different field names, which caused
    Posting Date, Sales Person, Tax Amount and Paid Without Tax to appear blank.
  */
  function normalizeReportRow(row){
    row=row||{};

    var paid=numberOrZero(row.paid_amount);

    var withoutGst=parseAmount(row.paid_amount_without_gst);
    if(withoutGst===null){ withoutGst=parseAmount(row.paid_amount_without_tax); }
    if(withoutGst===null){ withoutGst=parseAmount(row.amount_without_gst); }

    var gst=parseAmount(row.gst_amount);
    if(gst===null){ gst=parseAmount(row.tax_amount); }

    /*
      Fallback follows the supplied REFERRAL REPORT calculation:
          Paid without GST = Paid / 1.05
          GST              = Paid - Paid without GST
      The report-returned values are preferred whenever present.
    */
    if(withoutGst===null && paid>0){
      withoutGst=paid/1.05;
    }

    if(gst===null && paid>0){
      gst=paid-numberOrZero(withoutGst);
    }

    var referring=String(
      row.referring_employee ||
      row.custom_referring_name ||
      row.referring_name ||
      ''
    ).trim();

    var incentive=String(
      row.incentive_employee ||
      row.custom_incentive_employee_name ||
      row.incentive_employee_name ||
      ''
    ).trim();

    var copy=Object.assign({},row);

    /* Posting Date shown in the table is always the Sales Invoice date. */
    copy.posting_date=row.invoice_date || row.posting_date || '';

    copy.referring_employee=referring;
    copy.incentive_employee=incentive;

    copy.paid_amount=roundMoney(paid);
    copy.tax_amount=roundMoney(gst);
    copy.gst_amount=roundMoney(gst);
    copy.paid_amount_without_tax=roundMoney(withoutGst);
    copy.paid_amount_without_gst=roundMoney(withoutGst);

    return copy;
  }

  function rowMatchesSalesPerson(row,name){
    if(!name){ return true; }
    var target=String(name||'').trim().toLowerCase();
    var referring=String(row.referring_employee||'').trim().toLowerCase();
    var incentive=String(row.incentive_employee||'').trim().toLowerCase();
    return referring===target || incentive===target;
  }

  function renderSalesPersonCell(row){
    var referring=String(row.referring_employee||'').trim();
    var incentive=String(row.incentive_employee||'').trim();

    if(!referring && !incentive){ return ''; }

    var parts=[];

    if(referring){
      parts.push(
        '<div class="rr-sales-person-primary">'+
        escapeHtml(referring)+
        (incentive?' /':'')+
        '</div>'
      );
    }

    if(incentive){
      parts.push(
        '<div class="'+(referring?'rr-sales-person-secondary':'rr-sales-person-primary')+'">'+
        escapeHtml(incentive)+
        '</div>'
      );
    }

    return '<div class="rr-sales-person-cell">'+parts.join('')+'</div>';
  }
  function getHiddenValue(id){ var e=R.querySelector('#'+id); return e?e.value||'':''; }
  function getEffectiveBranch(){ return getHiddenValue('rr_branch'); }
  function getFilterSignature(){ return JSON.stringify({ from_date:fromEl.value, to_date:toEl.value, branch:getEffectiveBranch(), sales_person:getHiddenValue('rr_sp'), booking_type:getHiddenValue('rr_booking'), mode_of_payment:getHiddenValue('rr_mop'), customer:customerEl.value.trim(), paid_amount_from:paidFromEl.value.trim(), paid_amount_to:paidToEl.value.trim(), outstanding_operator:outstandingOperatorEl.value, outstanding_value:outstandingValueEl.value.trim() }); }
  function markFiltersChanged(m){ showMessage(m||'Filter changed. Click Apply Filters.','#697386'); }

  function closeAllSearchSelects(except){ R.querySelectorAll('.rr-ss').forEach(function(w){ if(w===except) return; w.classList.remove('rr-ss-open'); var d=w.querySelector('.rr-ss-drop'); if(d){ d.style.display='none'; } }); }
  function initSearchSelect(wrapperId){
    var w=R.querySelector('#'+wrapperId); if(!w) return;
    var hiddenId=w.getAttribute('data-id');
    var hidden=hiddenId?R.querySelector('#'+hiddenId):null;
    var display=w.querySelector('.rr-ss-display');
    var valueEl=w.querySelector('.rr-ss-val');
    var drop=w.querySelector('.rr-ss-drop');
    var search=w.querySelector('.rr-ss-search');
    var list=w.querySelector('.rr-ss-list');
    if(!hidden||!display||!valueEl||!drop||!search||!list){ return; }
    function filterOptions(q){ var n=String(q||'').toLowerCase(); list.querySelectorAll('.rr-ss-opt').forEach(function(o){ var t=o.textContent.toLowerCase(); o.style.display=(!n||t.indexOf(n)>=0)?'':'none'; }); }
    function open(){ closeAllSearchSelects(w); w.classList.add('rr-ss-open'); drop.style.display='block'; search.value=''; filterOptions(''); window.setTimeout(function(){ search.focus(); },0); }
    function close(){ w.classList.remove('rr-ss-open'); drop.style.display='none'; }
    function select(value,label,opts){ opts=opts||{}; hidden.value=value||''; valueEl.textContent=label||''; list.querySelectorAll('.rr-ss-opt').forEach(function(o){ o.classList.toggle('rr-ss-sel',o.getAttribute('data-val')===(value||'')); }); close(); if(!opts.silent){ markFiltersChanged(); } }
