  function formatDateForInput(d){ return d.getFullYear()+'-'+pad(d.getMonth()+1)+'-'+pad(d.getDate()); }
  function getCycleRange(){
    var now=new Date(); var day=now.getDate(); var month=now.getMonth()+1; var year=now.getFullYear();
    var fromYear,fromMonth,toYear,toMonth;
    if(day>=6){ fromYear=year; fromMonth=month; if(month===12){ toYear=year+1; toMonth=1; } else { toYear=year; toMonth=month+1; } }
    else { if(month===1){ fromYear=year-1; fromMonth=12; } else { fromYear=year; fromMonth=month-1; } toYear=year; toMonth=month; }
    return { from:fromYear+'-'+pad(fromMonth)+'-06', to:toYear+'-'+pad(toMonth)+'-05' };
  }
  function getQuickDateRange(key){
    var now=new Date(); var year=now.getFullYear(); var month=now.getMonth()+1; var day=now.getDate(); var today=formatDateForInput(now);
    if(key==='today'){ return { from:today, to:today }; }
    if(key==='yesterday'){ var y=new Date(now.getTime()-86400000); var v=formatDateForInput(y); return { from:v, to:v }; }
    if(key==='thismonth'){ return getCycleRange(); }
    if(key==='lastmonth'){
      var ccm,ccy;
      if(day>=6){ ccm=month; ccy=year; } else if(month===1){ ccm=12; ccy=year-1; } else { ccm=month-1; ccy=year; }
      var pcm=ccm-1; var pcy=ccy; if(pcm===0){ pcm=12; pcy-=1; }
      return { from:pcy+'-'+pad(pcm)+'-06', to:ccy+'-'+pad(ccm)+'-05' };
    }
    if(key==='thisquarter'){
      var qsm=1; if(month>=4&&month<=6){ qsm=4; } else if(month>=7&&month<=9){ qsm=7; } else if(month>=10&&month<=12){ qsm=10; }
      return { from:year+'-'+pad(qsm)+'-06', to:today };
    }
    if(key==='thisfy'){ var fys=month>=4?year:year-1; return { from:fys+'-04-01', to:(fys+1)+'-03-31' }; }
