  function isTotalRow(row){ if(!isObjectRow(row)) return false; return row.is_total_row===true||row.is_total_row===1||row.invoice==='Total'; }

  /*
    A restricted multi-branch login loads the report once per permitted branch.
    If the Query Report does not honor its Branch filter, the same invoice can
    come back from every request. Keep only rows belonging to the branch that
    was actually requested, and deduplicate the merged result as a second guard.
  */
  function normalizeBranchValue(value){
    return String(value===null||value===undefined?'':value).trim();
  }

  function reportRowKey(row){
    var invoice=String((row&&row.invoice)||'').trim();
    var branch=normalizeBranchValue(row&&row.branch);

    /* This report is invoice-based: one business row per invoice/branch. */
    if(invoice){
      return 'invoice|'+branch+'|'+invoice;
    }

    /* Defensive fallback for any row that unexpectedly has no invoice id. */
    return [
      branch,
      String((row&&row.posting_date)||''),
      String((row&&row.customer)||''),
      String((row&&row.booking_type)||''),
      String((row&&row.referring_employee)||''),
      String((row&&row.incentive_employee)||''),
      String((row&&row.mode_of_payment)||''),
      String(roundMoney(row&&row.paid_amount)),
      String(roundMoney(row&&row.tax_amount)),
      String(roundMoney(row&&row.paid_amount_without_tax)),
      String(roundMoney(row&&row.grand_total)),
      String(roundMoney(row&&row.outstanding_amount))
    ].join('|');
  }

  function deduplicateReportRows(rows){
    var seen=Object.create(null);
    var unique=[];
    var removed=0;

    (rows||[]).forEach(function(row){
      if(!isObjectRow(row)) return;
      var key=reportRowKey(row);
      if(seen[key]){
        removed+=1;
        return;
      }
      seen[key]=true;
      unique.push(row);
    });

    if(removed){
      void 0;
    }

    return unique;
  }

  function runReportForBranch(state,branch){
    return new Promise(function(resolve,reject){
      frappe.call({
        method:'frappe.desk.query_report.run',
        type:'GET',
        args:{
          report_name:REPORT_NAME,
          filters:{
            from_date:state.fromDate,
            to_date:state.toDate,
            branch:branch||''
          },
          ignore_prepared_report:1,
          are_default_filters:false
        },
        callback:function(response){
          var result=
            response &&
            response.message &&
            Array.isArray(response.message.result)
              ? response.message.result
              : [];

          var rows=result.map(function(row,si){
            if(!isObjectRow(row)) return null;
            if(isTotalRow(row)) return null;

            var copy=normalizeReportRow(row);
            var requestedBranch=normalizeBranchValue(branch);
            var returnedBranch=normalizeBranchValue(copy.branch);

            /*
              Never trust a branch-specific report request blindly. If the
              report accidentally returns another branch, discard that row.
            */
            if(requestedBranch && returnedBranch!==requestedBranch){
              void 0;
              return null;
            }

            copy.__rr_source_index=si;
            copy.__rr_fetch_branch=requestedBranch;
            return copy;
          }).filter(Boolean);

          resolve(rows);
        },
        error:function(err){
          reject(err);
        }
      });
    });
  }

  function fetchReportRows(state){
    var branchesToFetch=[];

    /*
      SECURITY RULE:
      Restricted + multiple branches + "All Branches" selected:
      never call the report with branch=''.
      Query each permitted branch separately and merge the results.
    */
    if(branchAccessRestricted && !state.branch && permittedBranches.length>1){
      branchesToFetch=permittedBranches.slice();
    } else {
      branchesToFetch=[state.branch||''];
    }

    totalRowSourceIndex=null;

    return Promise.all(
      branchesToFetch.map(function(branch){
        return runReportForBranch(state,branch);
      })
    ).then(function(groups){
      allRows=[];

      groups.forEach(function(rows){
        (rows||[]).forEach(function(row){
          allRows.push(row);
        });
      });

      /*
        Remove duplicates before any client-side filter is applied. This is
        especially important when All Branches means several report requests.
      */
      allRows=deduplicateReportRows(allRows);

      /*
        Additional protection: even after the server requests, never retain a
        row outside permittedBranches for a restricted login.
      */
      if(branchAccessRestricted && permittedBranches.length){
        allRows=allRows.filter(function(row){
          return permittedBranches.indexOf(String(row.branch||''))!==-1;
        });
      }

      populateSalesPersons(allRows);

      void 0;

      return allRows;
    });
  }

