          var isNumber=!!COLUMNS[idx].numeric;
          xml+='<Cell><Data ss:Type="'+(isNumber?'Number':'String')+'">'+
            xmlEscapeText(value)+
            '</Data></Cell>';
        });
        xml+='</Row>';
      });

      xml+='</Table></Worksheet></Workbook>';

      downloadBlob(
        baseName+'.xls',
        new Blob(
          [xml],
          {type:'application/vnd.ms-excel;charset=utf-8'}
        )
      );
    }

    showMessage(
      selectedFormat+
      ' download started for '+
      filteredRows.length+
      ' records across your permitted branches.',
      '#0d2b4e'
    );
  }

  function triggerExport(state){
    if(!allRows.length){ throw new Error('No loaded report data is available.'); }
    if(!filteredRows.length){ throw new Error('There are no filtered rows to download.'); }

    if(branchAccessRestricted && !state.branch && permittedBranches.length>1){
      exportRestrictedAllBranchesClientSide(state);
      return;
    }

    var args={ cmd:'frappe.desk.query_report.export_query', report_name:REPORT_NAME, custom_columns:[], file_format_type:selectedFormat, filters:{ from_date:state.fromDate, to_date:state.toDate, branch:state.branch||'' }, applied_filters:getAppliedFilterLabels(state), visible_idx:getVisibleSourceIndexes(), include_filters:1, include_indentation:0, include_hidden_columns:0, export_in_background:0, csv_delimiter:',', csv_quoting:0 };
    var url=window.frappe&&frappe.request&&frappe.request.url?frappe.request.url:'/api/method';
    var postHelper=null;
    if(typeof window.open_url_post==='function'){ postHelper=window.open_url_post; }
    else if(window.frappe&&frappe.utils&&typeof frappe.utils.open_url_post==='function'){ postHelper=frappe.utils.open_url_post; }
    if(postHelper){ postHelper(url,args); } else { submitDownloadFallback(url,args); }
    showMessage(selectedFormat+' download started for '+filteredRows.length+' filtered records.','#0d2b4e');
  }
  function applyBeforeDownload(state){
    var sig=getFilterSignature();
    if(allRows.length&&lastAppliedSignature===sig){ applyClientFilters(state); return Promise.resolve(state); }
    setBusyState(true,downloadButton);
    showMessage('Refreshing the report before download…','#595959');
    return fetchReportRows(state).then(function(){
      var rs=getValidatedFilterState(true);
      if(!rs){ throw new Error('Filter validation failed.'); }
      applyClientFilters(rs);
      lastAppliedSignature=getFilterSignature();
      return rs;
    }).catch(function(err){
      void 0;
      showMessage('Unable to prepare the report for download.','#c0392b');
      throw err;
    }).finally(function(){ setBusyState(false); });
  }

  R.querySelector('.rr-qrow').addEventListener('click',function(e){
    var b=e.target.closest('.rr-qbtn'); if(!b) return;
    R.querySelectorAll('.rr-qbtn').forEach(function(i){ i.classList.remove('rr-qbtn-on'); });
    b.classList.add('rr-qbtn-on');
    var range=getQuickDateRange(b.getAttribute('data-q'));
    fromEl.value=range.from; toEl.value=range.to;
    markFiltersChanged('Date range changed. Click Apply Filters.');
  });
  R.querySelector('.rr-fmtrow').addEventListener('click',function(e){
    var chip=e.target.closest('.rr-fchip'); if(!chip) return;
    R.querySelectorAll('.rr-fchip').forEach(function(i){ i.classList.remove('rr-fchip-on'); i.setAttribute('aria-pressed','false'); });
    chip.classList.add('rr-fchip-on'); chip.setAttribute('aria-pressed','true');
    selectedFormat=chip.getAttribute('data-f')==='csv'?'CSV':'Excel';
  });
  outstandingOperatorEl.addEventListener('change',function(){ updateOutstandingInputState(); markFiltersChanged(); });
  [fromEl,toEl].forEach(function(el){ el.addEventListener('change',function(){ R.querySelectorAll('.rr-qbtn').forEach(function(b){ b.classList.remove('rr-qbtn-on'); }); markFiltersChanged('Date changed. Click Apply Filters.'); }); });
  [customerEl,paidFromEl,paidToEl,outstandingValueEl].forEach(function(el){ el.addEventListener('input',function(){ markFiltersChanged(); }); });
  [fromEl,toEl,customerEl,paidFromEl,paidToEl,outstandingValueEl].forEach(function(el){ el.addEventListener('keydown',function(e){ if(e.key!=='Enter') return; e.preventDefault(); applyButton.click(); }); });
  applyButton.addEventListener('click',function(e){ e.preventDefault(); if(requestInProgress) return; var state=getValidatedFilterState(true); if(!state) return; loadAndApply(state).catch(function(){}); });
  downloadButton.addEventListener('click',function(e){
    e.preventDefault(); if(requestInProgress) return;
    var state=getValidatedFilterState(true); if(!state) return;
    setButtonState(downloadButton,true,'Preparing...','Generate & Download');
    applyBeforeDownload(state).then(function(fs){ triggerExport(fs); }).catch(function(err){
      void 0;
      showMessage(err&&err.message?err.message:'Download failed.','#c0392b');
    }).finally(function(){ window.setTimeout(function(){ setButtonState(downloadButton,false,'','Generate & Download'); },700); });
  });

  updateOutstandingInputState();

  /*
    PERMISSION-AWARE BRANCH SETUP

    Important:
    - Never preserve the hardcoded branch options from the HTML.
    - Ask ERPNext for Branch records using frappe.client.get_list.
    - Non-privileged users receive only those returned/permitted branches.
    - A one-branch login is selected automatically and locked.
    - Multi-branch restricted users may switch only among their permitted branches.
    - Privileged roles keep the All Branches option.
  */
  var RR_ALL_ACCESS_ROLES=[
    'System Manager'
  ];

  function userHasAllBranchAccess(){
    if(frappe.session && frappe.session.user==='Administrator'){
      return true;
    }

    if(frappe.user && typeof frappe.user.has_role==='function'){
      for(var i=0;i<RR_ALL_ACCESS_ROLES.length;i+=1){
        if(frappe.user.has_role(RR_ALL_ACCESS_ROLES[i])){
          return true;
        }
      }
    }

    var roles=
      frappe.user_roles ||
      (frappe.boot && frappe.boot.user && frappe.boot.user.roles) ||
      [];

    for(var j=0;j<RR_ALL_ACCESS_ROLES.length;j+=1){
      if(roles.indexOf(RR_ALL_ACCESS_ROLES[j])!==-1){
        return true;
      }
    }

    return false;
  }

  function setBranchDropdown(names,allowAll){
    var w=R.querySelector('#rr_ss_branch');
    var list=w&&w._rrList;
    var display=w&&w.querySelector('.rr-ss-display');

    if(!w||!list||!w._rrSelect){
      return false;
    }

    names=(names||[]).filter(Boolean);
    names=names.filter(function(name,index,array){
      return array.indexOf(name)===index;
    });

    names.sort(function(a,b){
      return a.localeCompare(b,undefined,{sensitivity:'base'});
    });

    list.innerHTML='';

    if(allowAll){
      var all=document.createElement('div');
      all.className='rr-ss-opt';
      all.setAttribute('data-val','');
      all.textContent='All Branches';
      list.appendChild(all);
    }

    names.forEach(function(name){
      var opt=document.createElement('div');
      opt.className='rr-ss-opt';
      opt.setAttribute('data-val',name);
      opt.textContent=name;
      list.appendChild(opt);
    });

    if(display){
      display.style.pointerEvents='';
      display.style.opacity='';
      display.setAttribute('tabindex','0');
    }

    return true;
  }

  function lockSingleBranch(branch){
    var w=R.querySelector('#rr_ss_branch');
    var display=w&&w.querySelector('.rr-ss-display');

    if(w&&w._rrSelect){
      w._rrSelect(branch,branch,{silent:true});
    }

    if(display){
      display.style.pointerEvents='none';
      display.style.opacity='0.78';
      display.setAttribute('tabindex','-1');
      display.setAttribute('title','Your login is restricted to '+branch);
    }

    userBranch=branch;
  }

  function loadPermittedBranches(){
    return new Promise(function(resolve,reject){
      frappe.call({
        method:'frappe.client.get_list',
        args:{
          doctype:'Branch',
          fields:['name'],
          limit_page_length:200,
          order_by:'name asc'
        },
        callback:function(response){
          var rows=response&&Array.isArray(response.message)?response.message:[];
          var names=rows.map(function(row){
            return String((row&&row.name)||'').trim();
          }).filter(Boolean);

          var allAccess=userHasAllBranchAccess();

          permittedBranches=names.slice();
          branchAccessRestricted=!allAccess;

          if(allAccess){
            setBranchDropdown(names,true);
            var wAll=R.querySelector('#rr_ss_branch');
            if(wAll&&wAll._rrSelect){
              wAll._rrSelect('','All Branches',{silent:true});
            }
            userBranch='';

            void 0;

            resolve();
            return;
          }

          if(!names.length){
            reject(new Error(
              'No permitted Branch was returned for this login.'
            ));
            return;
          }

          /*
            Restricted user:
            - one permitted branch  -> show only that branch and lock it
            - multiple branches     -> show All Branches + permitted branches
              where All Branches means all permitted branches only
          */
          if(names.length===1){
            setBranchDropdown(names,false);
            lockSingleBranch(names[0]);
          } else {
            setBranchDropdown(names,true);

            var w=R.querySelector('#rr_ss_branch');
            if(w&&w._rrSelect){
              w._rrSelect('','All Branches',{silent:true});
            }

            userBranch='';
          }

          void 0;

          resolve();
        },
        error:function(err){
          reject(err||new Error('Unable to determine permitted branches.'));
        }
      });
    });
  }

  function initialLoad(){
    var state=getValidatedFilterState(true);
    if(!state) return;
    loadAndApply(state).catch(function(){});
  }

  function boot(){
    loadPermittedBranches()
      .then(function(){
        initialLoad();
      })
      .catch(function(err){
        void 0;

        tableWrapper.innerHTML='';
        applyButton.disabled=true;
        downloadButton.disabled=true;

        showMessage(
          'Branch access could not be verified for this login. Report loading has been blocked.',
          '#c0392b'
        );
      });
  }

  if(window.frappe&&frappe.call&&frappe.session){
    boot();
  } else {
    var tries=0;
    var timer=setInterval(function(){
      tries+=1;

      if(window.frappe&&frappe.call&&frappe.session){
        clearInterval(timer);
        boot();
      } else if(tries>50){
        clearInterval(timer);
        showMessage('Frappe not available on this page.','#c0392b');
      }
    },100);
  }
})();
